/** Applies and persists the local (browser-only) theme/sidebar/wallpaper
 * preference. See theme.ts for why this is not a backend-persisted setting. */
function useUIPreferences() {
  const [preferences, setPreferences] = useState<UIPreferences>(() => loadPreferences());
  useEffect(() => { applyTheme(resolveTheme(preferences.theme)); applySidebarCollapsed(preferences.sidebarCollapsed); applyWallpaper(preferences.wallpaper); applyBaseColors(preferences.baseColorDark, preferences.baseColorLight); }, [preferences]);
  useEffect(() => {
    if (preferences.theme !== 'system' || typeof window.matchMedia !== 'function') return;
    const query = window.matchMedia('(prefers-color-scheme: dark)');
    const onChange = () => applyTheme(resolveTheme('system', query.matches));
    query.addEventListener('change', onChange);
    return () => query.removeEventListener('change', onChange);
  }, [preferences.theme]);
  const update = (next: Partial<UIPreferences>) => setPreferences(current => savePreferences({ ...current, ...next }));
  return { preferences, update };
}

type User = { id: string; username: string; display_name: string; is_admin: boolean };
type PasswordPolicy = { password_minimum_length: number; password_maximum_length: number };
type Me = { user: User; csrf_token: string; capabilities?: string[]; password_policy: PasswordPolicy; branding: Branding };
type SetupStorage = { data_directory: string; database_path: string };
type SetupStatus = { setup_required: boolean; storage?: SetupStorage; password_policy: PasswordPolicy; branding: Branding };
type SteamCMDStatus = { status: 'idle' | 'preparing' | 'ready' | 'failed' | 'unavailable'; summary: string };
type ContainerConfiguration = { image: string; command: string[]; memory_limit_bytes: number; cpu_limit_millis: number; image_availability?: 'available' | 'missing' | 'engine_unavailable'; pull_state?: 'idle' | 'pulling' | 'failed' };
type GameServer = { id: string; tenant_id: string; creation_mode: 'new' | 'adopt' | 'custom' | 'template'; name: string; description: string; working_directory: string; executable: string; arguments: string[]; environment_variables: Record<string, string>; runtime_type: 'native' | 'container'; container?: ContainerConfiguration; auto_start: boolean; restart_policy: 'never'; stop_method: 'terminate' | 'stdin_command' | 'console_interrupt'; stop_command: string; stop_timeout_seconds: number; auto_restart_enabled: boolean; auto_restart_max_attempts: number; auto_restart_window_seconds: number; auto_restart_delay_seconds: number };
type ServerRecord = { server: GameServer; runtime: { pid?: number; current_state: string; console_detached?: boolean; last_error?: string }; capabilities?: string[]; tenant_name?: string };
type Monitoring = { health: string; uptime_seconds?: number; cpu_percent?: number; memory_bytes?: number; crash_count?: number; restart_count?: number; auto_restart_enabled?: boolean; pending_auto_restart?: boolean; restart_limit_reached?: boolean };
type MonitoringSample = { timestamp: string; cpu_percent: number; memory_bytes: number; thread_count?: number };
type ServerAction = 'start' | 'stop' | 'restart' | 'kill' | 'delete';

const percent = (value?: number): string => typeof value === 'number' && Number.isFinite(value) ? `${value.toFixed(1)}%` : 'Unavailable';

const api = async <T,>(path: string, init?: RequestInit): Promise<T> => {
  const response = await fetch(`/api/v1${path}`, { credentials: 'same-origin', headers: { 'Content-Type': 'application/json', ...(init?.headers ?? {}) }, ...init });
  if (!response.ok) {
    const body = await response.json().catch(() => null);
    throw new Error(body?.error?.message ?? 'Request failed');
  }
  return response.status === 204 ? undefined as T : response.json();
};
const csrf = (token: string) => ({ 'X-CSRF-Token': token });

function SetupStorageForm({ storage, onContinue }: { storage: SetupStorage; onContinue: () => void }) {
  const [dataDirectory, setDataDirectory] = useState(storage.data_directory); const [databasePath, setDatabasePath] = useState(storage.database_path); const [error, setError] = useState(''); const [restart, setRestart] = useState(false);
  async function save(event: FormEvent) { event.preventDefault(); setError(''); if (dataDirectory === storage.data_directory && databasePath === storage.database_path) { onContinue(); return; } try { await api('/setup/config', { method: 'PATCH', body: JSON.stringify({ data_directory: dataDirectory, database_path: databasePath }) }); setRestart(true); } catch (reason) { setError(reason instanceof Error ? reason.message : 'Request failed'); } }
  if (restart) return <main className="auth"><section className="card"><p className="eyebrow">SETUP · CONFIGURATION SAVED</p><h1>Restart GameNode</h1><p>The database, server, log, and SteamCMD paths change only on restart. Stop this process and start the executable again to continue with administrator setup.</p></section></main>;
  return <main className="auth"><section className="card"><p className="eyebrow">SETUP · STEP 1 OF 2</p><h1>Choose storage paths</h1><p>Defaults keep all managed data beside the configuration file. Absolute paths make the deployment location predictable.</p><form onSubmit={save}><label>Data directory<input value={dataDirectory} onChange={event => setDataDirectory(event.target.value)} required /></label><label>Database file<input value={databasePath} onChange={event => setDatabasePath(event.target.value)} required /></label><p className="hint">Logs, SteamCMD, templates, and managed server files are placed below the data directory.</p>{error && <p className="error">{error}</p>}<button>Continue</button></form></section></main>;
}

function Credentials({ setup, passwordPolicy, onComplete }: { setup: boolean; passwordPolicy: PasswordPolicy; onComplete: (me: Me) => void }) {
	const [username, setUsername] = useState(''); const [email, setEmail] = useState(''); const [password, setPassword] = useState(''); const [prepareSteamCMD, setPrepareSteamCMD] = useState(setup); const [error, setError] = useState(''); const [steam, setSteam] = useState<SteamCMDStatus>(); const [completed, setCompleted] = useState<Me>();
	async function submit(event: FormEvent) { event.preventDefault(); try { const current = await api<Me>(setup ? '/setup' : '/auth/login', { method: 'POST', body: JSON.stringify(setup ? { username, email, password, prepare_steamcmd: prepareSteamCMD } : { username, password }) }); if (!setup || !prepareSteamCMD) { onComplete(current); return; } for (let attempt = 0; attempt < 150; attempt++) { const state = await api<SteamCMDStatus>('/setup/steamcmd'); setSteam(state); if (state.status === 'ready' || state.status === 'failed') { setCompleted(current); return; } await new Promise(resolve => window.setTimeout(resolve, 1000)); } setSteam({ status: 'failed', summary: 'SteamCMD preparation timed out' }); setCompleted(current); } catch (reason) { setError(reason instanceof Error ? reason.message : 'Request failed'); } }
	if (steam && completed) return <main className="auth"><section className="card"><p className="eyebrow">SETUP · STEAMCMD</p><h1>{steam.status === 'ready' ? 'SteamCMD is ready' : 'SteamCMD preparation failed'}</h1><p className={steam.status === 'failed' ? 'error' : ''}>{steam.summary}</p><p className="hint">You can continue now. A failed preparation can be retried later by creating a SteamCMD game server.</p><button onClick={() => onComplete(completed)}>Continue to GameNode</button></section></main>;
	return <main className="auth"><section className="card"><p className="eyebrow">GAMENODE</p><h1>{setup ? 'Create administrator' : 'Welcome back'}</h1><form onSubmit={submit}>{setup && <><label>Email<input type="email" value={email} onChange={event => setEmail(event.target.value)} required /></label><label><input type="checkbox" checked={prepareSteamCMD} onChange={event => setPrepareSteamCMD(event.target.checked)} />Download and prepare SteamCMD now</label><p className="hint">SteamCMD is downloaded only from Valve's fixed official source. You can also prepare it later by installing a SteamCMD game.</p></>}<label>Username<input value={username} onChange={event => setUsername(event.target.value)} required /></label><label>Password<input type="password" value={password} onChange={event => setPassword(event.target.value)} minLength={setup ? passwordPolicy.password_minimum_length : undefined} maxLength={setup ? passwordPolicy.password_maximum_length : undefined} required /></label>{setup && <p className="hint">Use {passwordPolicy.password_minimum_length}–{passwordPolicy.password_maximum_length} characters.</p>}{error && <p className="error">{error}</p>}<button>{setup ? 'Complete setup' : 'Sign in'}</button></form></section></main>;
}

const empty = (): GameServer => ({ id: '', tenant_id: '', creation_mode: 'custom', name: '', description: '', working_directory: '', executable: '', arguments: [], environment_variables: {}, runtime_type: 'native', auto_start: false, restart_policy: 'never', stop_method: 'terminate', stop_command: '', stop_timeout_seconds: 15, auto_restart_enabled: false, auto_restart_max_attempts: 3, auto_restart_window_seconds: 300, auto_restart_delay_seconds: 5 });

function ServerForm({ initial, token, onDone, onCancel }: { initial?: GameServer; token: string; onDone: (record: ServerRecord) => void; onCancel: () => void }) {
  const [value, setValue] = useState(initial ?? empty()); const [args, setArgs] = useState((initial?.arguments ?? []).join('\n')); const [env, setEnv] = useState(Object.entries(initial?.environment_variables ?? {}).map(([key, entry]) => `${key}=${entry}`).join('\n')); const [container, setContainer] = useState<ContainerCreateDraft>(() => containerDraftFromValues(initial) ?? defaultContainerCreateDraft()); const [error, setError] = useState('');
  // Adopt Existing / Custom Application accept an arbitrary host working
  // directory, so this form is reachable only through global Server.Create;
  // every tenant is therefore offered here (GET /servers/creatable-tenants
  // returns every tenant for a global grant). See docs/architecture.md's
  // Tenant Foundation Step 4/5 sections on why this must never be reachable
  // with a tenant-scoped-only grant.
  const { tenants } = useCreatableTenants();
  const selection = resolveTenantSelection(tenants);
  useEffect(() => { if (!initial && selection.preselected && !value.tenant_id) setValue(current => ({ ...current, tenant_id: selection.preselected })); }, [selection.preselected]);
  async function submit(event: FormEvent) { event.preventDefault(); try { const variables: Record<string, string> = {}; env.split('\n').filter(Boolean).forEach(line => { const index = line.indexOf('='); if (index < 1) throw new Error('Environment lines must be KEY=VALUE'); variables[line.slice(0, index)] = line.slice(index + 1); }); const payload = !initial ? buildServerCreatePayload(value, args.split('\n').filter(Boolean), variables, container) : value.runtime_type === 'container' ? buildContainerServerUpdatePayload(value, container) : { ...value, arguments: args.split('\n').filter(Boolean), environment_variables: variables }; onDone(await api<ServerRecord>(initial ? `/servers/${initial.id}` : '/servers', { method: initial ? 'PATCH' : 'POST', headers: csrf(token), body: JSON.stringify(payload) })); } catch (reason) { setError(reason instanceof Error ? reason.message : 'Request failed'); } }
  const isContainer = value.runtime_type === 'container';
  return <section className="panel form-panel"><div className="row"><h2>{initial ? 'Edit server' : 'Add server'}</h2><button className="quiet" type="button" onClick={onCancel}>Cancel</button></div><form onSubmit={submit}>{!initial && <label>Tenant<select value={value.tenant_id} onChange={event => setValue({ ...value, tenant_id: event.target.value })} required><option value="">Choose tenant…</option>{tenants.map(tenant => <option key={tenant.id} value={tenant.id}>{tenant.name}</option>)}</select></label>}{initial && <label>Tenant<input value={initial.tenant_id} readOnly disabled /></label>}{!initial && <p className="hint">A server's tenant is set at creation. A GameNode administrator can migrate a stopped server later.</p>}{!initial && <label>Runtime<select value={value.runtime_type} onChange={event => setValue({ ...value, runtime_type: event.target.value as GameServer['runtime_type'] })}><option value="native">Native</option><option value="container">Container</option></select></label>}{initial && <label>Runtime<input value={value.runtime_type === 'container' ? 'Container' : 'Native'} readOnly disabled /></label>}<label>Workflow<select value={value.creation_mode} onChange={event => setValue({ ...value, creation_mode: event.target.value as GameServer['creation_mode'] })}>{value.creation_mode==='template'&&<option value="template" disabled>Built-in template</option>}<option value="new">Create New</option><option value="adopt">Adopt Existing</option><option value="custom">Custom Application</option></select></label><p className="hint">Adopt Existing only registers existing paths; it never changes files. An externally adopted server's tenant boundary is logical only - GameNode's managed tenant storage isolation does not apply to it.</p><label>Name<input value={value.name} onChange={event => setValue({ ...value, name: event.target.value })} required /></label><label>Description<textarea value={value.description} onChange={event => setValue({ ...value, description: event.target.value })} /></label><label>Working directory<input value={value.working_directory} onChange={event => setValue({ ...value, working_directory: event.target.value })} required /></label>{isContainer ? <><label>Container image<input value={container.image} onChange={event => setContainer({ ...container, image: event.target.value })} placeholder="itzg/minecraft-server:latest" required /></label><label>CPU limit <span className="hint">millicores</span><input type="number" min="10" max="1000000" step="1" value={container.cpuLimitMillis} onChange={event => setContainer({ ...container, cpuLimitMillis: event.target.value })} required /></label><label>Memory limit <span className="hint">MiB</span><input type="number" min="16" max="1073741824" step="1" value={container.memoryLimitMiB} onChange={event => setContainer({ ...container, memoryLimitMiB: event.target.value })} required /></label><label>Container command <span className="hint">one argument per line; no shell</span><textarea value={container.command} onChange={event => setContainer({ ...container, command: event.target.value })} /></label></> : <><label>Executable<input value={value.executable} onChange={event => setValue({ ...value, executable: event.target.value })} required /></label><label>Arguments <span className="hint">one per line</span><textarea value={args} onChange={event => setArgs(event.target.value)} /></label><label>Environment <span className="hint">KEY=VALUE, one per line</span><textarea value={env} onChange={event => setEnv(event.target.value)} /></label></>}<label>Stop method<select value={value.stop_method} onChange={event=>setValue({...value,stop_method:event.target.value as GameServer['stop_method'],stop_command:event.target.value==='stdin_command'?value.stop_command:''})}><option value="terminate">Terminate process</option><option value="stdin_command">Console command</option><option value="console_interrupt">Windows console interrupt</option></select></label>{value.stop_method==='stdin_command'&&<label>Stop command<input value={value.stop_command} onChange={event=>setValue({...value,stop_command:event.target.value})} placeholder="stop" required /></label>}{value.stop_method==='console_interrupt'&&<p className="hint">Sends a targeted Windows console interrupt (CTRL_BREAK) to this process only, then falls back to force-kill after the stop timeout. Unavailable for a process rediscovered after a GameNode restart, and unsupported outside Windows.</p>}<label>Stop timeout (seconds)<input type="number" min="1" max="300" value={value.stop_timeout_seconds} onChange={event => setValue({ ...value, stop_timeout_seconds: Number(event.target.value)})} /></label><label><input type="checkbox" checked={value.auto_restart_enabled} onChange={event=>setValue({...value,auto_restart_enabled:event.target.checked})}/> Enable automatic restart after unexpected exits</label>{value.auto_restart_enabled&&<><label>Maximum attempts<input type="number" min="1" max="20" value={value.auto_restart_max_attempts} onChange={event=>setValue({...value,auto_restart_max_attempts:Number(event.target.value)})}/></label><label>Attempt window (seconds)<input type="number" min="1" max="86400" value={value.auto_restart_window_seconds} onChange={event=>setValue({...value,auto_restart_window_seconds:Number(event.target.value)})}/></label><label>Restart delay (seconds)<input type="number" min="0" max="3600" value={value.auto_restart_delay_seconds} onChange={event=>setValue({...value,auto_restart_delay_seconds:Number(event.target.value)})}/></label></>}{error && <p className="error">{error}</p>}<button>Save server</button></form></section>;
}

function ServerDetail({ record, token, onBack, onEdit, onAction, error }: { record: ServerRecord; token: string; onBack: () => void; onEdit: () => void; onAction: (action: ServerAction) => void; error: string }) {
  const [tab, setTab] = useState<'overview' | 'console' | 'files' | 'ports' | 'configuration'>('overview');
  const [monitoring, setMonitoring] = useState<Monitoring>();
  const can = (permission: string) => hasCapability(record.capabilities, permission);
  useEffect(() => { if (!can('Monitoring.View')) { setMonitoring(undefined); return; } const load = () => api<Monitoring>(`/servers/${record.server.id}/monitoring`).then(setMonitoring).catch(() => setMonitoring(undefined)); load(); const timer = window.setInterval(load, 5000); return () => window.clearInterval(timer); }, [record.server.id, record.capabilities]);
  const action = (label: string, permission: string, name: ServerAction, className?: string) => can(permission) && <button className={className} onClick={() => onAction(name)}>{label}</button>;
  const bytes=(value?:number)=>Number.isFinite(value)?(value!>=1024*1024?`${(value!/1024/1024).toFixed(1)} MiB`:`${value} B`):'Unavailable';
  return <section className="panel"><div className="row"><div><p className="eyebrow">{record.server.creation_mode}</p><h2>{record.server.name}</h2></div><button className="quiet" onClick={onBack}>Back</button></div><p><span className={`status ${serverStateTone(record.runtime.current_state)}`}>{serverStateLabel(record.runtime.current_state)}</span>{record.runtime.pid ? ` PID ${record.runtime.pid}` : ''}</p><nav className="detail-tabs"><button className={tab === 'overview' ? 'active' : ''} onClick={() => setTab('overview')}>Overview</button>{can('Console.View') && <button className={tab === 'console' ? 'active' : ''} onClick={() => setTab('console')}>Console</button>}{can('Files.View') && <button className={tab === 'files' ? 'active' : ''} onClick={() => setTab('files')}>Files</button>}{can('Ports.View') && <button className={tab === 'ports' ? 'active' : ''} onClick={() => setTab('ports')}>Ports</button>}{can('Server.Edit') && <button className={tab === 'configuration' ? 'active' : ''} onClick={() => setTab('configuration')}>Configuration</button>}</nav>{tab === 'overview' && <><p className="muted">{record.server.working_directory}<br />{record.server.executable}</p>{can('Monitoring.View') && monitoring && <section className="monitoring"><div><small>Health</small><strong>{healthLabel(monitoring.health)}</strong></div><div><small>Uptime</small><strong>{metric(monitoring.uptime_seconds,'s')}</strong></div><div><small>CPU</small><strong>{percent(monitoring.cpu_percent)}</strong></div><div><small>Memory</small><strong>{bytes(monitoring.memory_bytes)}</strong></div><div><small>Crashes</small><strong>{metric(monitoring.crash_count)}</strong></div><div><small>Restarts</small><strong>{metric(monitoring.restart_count)}</strong></div><div><small>Auto-restart</small><strong>{monitoring.auto_restart_enabled?'Enabled':'Disabled'}</strong></div><div><small>Pending restart</small><strong>{monitoring.pending_auto_restart?'Pending restart':'—'}</strong></div><div><small>Restart limit</small><strong>{monitoring.restart_limit_reached?'Restart limit reached':'—'}</strong></div></section>}{record.runtime.last_error && <p className="error">{record.runtime.last_error}</p>}<div className="actions">{action('Start', 'Server.Start', 'start')}{action('Stop', 'Server.Stop', 'stop')}{action('Restart', 'Server.Restart', 'restart')}{action('Kill', 'Server.Kill', 'kill', 'danger')}{can('Server.Edit') && <button className="quiet" onClick={onEdit}>Edit</button>}{action('Delete', 'Server.Delete', 'delete', 'danger quiet')}</div></>}{tab === 'console' && can('Console.View') && <ConsoleTab serverID={record.server.id} serverState={record.runtime.current_state} canSend={can('Console.Send')} />}{tab === 'files' && can('Files.View') && <FilesTab serverID={record.server.id} token={token} permissions={record.capabilities} />}{tab === 'ports' && can('Ports.View') && <PortsTab serverID={record.server.id} token={token} canManage={can('Ports.Manage')} />}{tab === 'configuration' && can('Server.Edit') && <p className="muted">{record.server.working_directory}<br />{record.server.executable}</p>}{error && <p className="error">{error}</p>}</section>;
}

function Sparkline({ samples, field, label, format }: { samples: MonitoringSample[]; field: 'cpu_percent' | 'memory_bytes'; label: string; format: (value: number) => string }) {
  const values = samples.map(sample => sample[field]).filter(Number.isFinite);
  if (values.length < 2) return <EmptyState compact title={`No ${label.toLowerCase()} history`} description="Charts appear after at least two monitoring samples have been collected." icon={Gauge} />;
  const max = Math.max(...values, field === 'cpu_percent' ? 100 : 1), min = field === 'cpu_percent' ? 0 : Math.min(...values);
  const points = values.map((value, index) => `${values.length === 1 ? 0 : index / (values.length - 1) * 100},${38 - ((value - min) / Math.max(1, max - min)) * 34}`).join(' ');
  return <article className="chart-card"><div><span>{label}</span><strong>{format(values.at(-1)!)}</strong></div><svg viewBox="0 0 100 40" preserveAspectRatio="none" role="img" aria-label={`${label} monitoring history`}><polyline className="chart-area" points={`0,40 ${points} 100,40`} /><polyline className="chart-line" points={points} /></svg><footer><span>{samples.length} samples</span><span>Peak {format(Math.max(...values))}</span></footer></article>;
}

function TenantMigrationDialog({ server, token, onCancel, onCompleted }: { server: ServerRecord; token: string; onCancel: () => void; onCompleted: (record: ServerRecord) => void }) {
  const [tenants, setTenants] = useState<{ id: string; name: string }[]>([]); const [target, setTarget] = useState(''); const [loading, setLoading] = useState(true); const [saving, setSaving] = useState(false); const [error, setError] = useState('');
  useEffect(() => { api<{ tenants: { id: string; name: string }[] }>('/tenants').then(result => setTenants((result.tenants ?? []).filter(item => item.id !== server.server.tenant_id))).catch(() => setError('Tenants could not be loaded.')).finally(() => setLoading(false)); }, [server.server.tenant_id]);
  async function submit(event: FormEvent) { event.preventDefault(); if (!target) return; setSaving(true); setError(''); try { const result = await api<ServerRecord>(`/servers/${server.server.id}/tenant`, { method: 'POST', headers: csrf(token), body: JSON.stringify({ tenant_id: target }) }); onCompleted(result); } catch (reason) { setError(reason instanceof Error ? reason.message : 'Tenant migration failed.'); } finally { setSaving(false); } }
  return <section className="panel form-panel"><SectionHeader title="Migrate provisioned server" description="GameNode moves the managed server directory and updates its tenant ownership." /><p className="notice notice--warning">The server must be stopped. Only provisioned servers in managed tenant storage can be physically migrated. Access permissions change immediately after migration.</p><form onSubmit={submit}><label>Current tenant<input value={server.tenant_name || server.server.tenant_id} disabled readOnly /></label><label>Target tenant<select value={target} onChange={event => setTarget(event.target.value)} disabled={loading || saving} required><option value="">{loading ? 'Loading tenants…' : tenants.length ? 'Choose tenant…' : 'No other tenants available'}</option>{tenants.map(item => <option key={item.id} value={item.id}>{item.name}</option>)}</select></label>{error && <p className="error notice">{error}</p>}<div className="actions"><button disabled={saving || loading || !target}>{saving ? 'Migrating…' : 'Migrate server'}</button><button type="button" className="quiet" onClick={onCancel} disabled={saving}>Cancel</button></div></form></section>;
}

function ServerDetailModern({ record, token, globalCapabilities, isAdmin, onBack, onEdit, onAction, onUpdate, onRefresh, onOpenRoles, onOpenTenant, onMigrate, error }: { record: ServerRecord; token: string; globalCapabilities?: string[]; isAdmin: boolean; onBack: () => void; onEdit: () => void; onAction: (action: ServerAction) => void; onUpdate: () => void; onRefresh: () => void; onOpenRoles?: () => void; onOpenTenant?: (id: string) => void; onMigrate: () => void; error: string }) {
  const [tab, setTab] = useState<'overview' | 'monitoring' | 'console' | 'files' | 'ftp' | 'ports' | 'configuration' | 'access'>('overview');
  const [monitoring, setMonitoring] = useState<Monitoring>();
  const [history, setHistory] = useState<MonitoringSample[]>([]);
  const [configuration, setConfiguration] = useState<GameConfigAdapterSummary[]>();
  const [containerPorts, setContainerPorts] = useState<PortSummary[]>();
  const [portsLoading, setPortsLoading] = useState(false);
  const [portsError, setPortsError] = useState(false);
  const [pullSubmitting, setPullSubmitting] = useState(false);
  const [pullError, setPullError] = useState(false);
  const can = (permission: string) => hasCapability(record.capabilities, permission);
  const isContainer = isContainerRuntime(record.server.runtime_type);
  const container = isContainer ? record.server.container : undefined;
  const pullState = pullSubmitting ? 'pulling' : container?.pull_state ?? 'idle';
  const imageAvailability = container?.image_availability;
  const pullEnabled = canPullContainer(record.server.runtime_type, imageAvailability, pullState, can('Server.Edit'));
  const pullActionVisible = isContainer && can('Server.Edit') && (imageAvailability === 'available' || imageAvailability === 'missing');
  useEffect(() => { if (!can('Server.View')) { setConfiguration(undefined); return; } api<{ available: boolean; adapters: GameConfigAdapterSummary[] }>(`/servers/${record.server.id}/configuration`).then(data => setConfiguration(data.available ? data.adapters : undefined)).catch(() => setConfiguration(undefined)); }, [record.server.id, record.capabilities]);
  useEffect(() => { if (!can('Monitoring.View')) { setMonitoring(undefined); setHistory([]); return; } const load = () => Promise.all([api<Monitoring>(`/servers/${record.server.id}/monitoring`), api<{ samples: MonitoringSample[] }>(`/servers/${record.server.id}/monitoring/history`)]).then(([current, samples]) => { setMonitoring(current); setHistory(samples.samples ?? []); }).catch(() => { setMonitoring(undefined); setHistory([]); }); load(); const timer = window.setInterval(load, 5000); return () => window.clearInterval(timer); }, [record.server.id, record.capabilities]);
  useEffect(() => {
    if (!isContainer || !can('Ports.View')) { setContainerPorts(undefined); setPortsError(false); setPortsLoading(false); return; }
    let cancelled = false;
    setPortsLoading(true); setPortsError(false);
    api<{ ports: PortSummary[] | null }>(`/servers/${record.server.id}/ports`).then(value => { if (!cancelled) setContainerPorts(listOrEmpty(value.ports)); }).catch(() => { if (!cancelled) { setContainerPorts([]); setPortsError(true); } }).finally(() => { if (!cancelled) setPortsLoading(false); });
    return () => { cancelled = true; };
  }, [isContainer, record.server.id, record.capabilities]);
  async function pullImage() {
    if (!container || !pullEnabled || pullSubmitting) return;
    setPullError(false); setPullSubmitting(true);
    const request = containerPullRequest(record.server.id, token);
    try { await api<{ image_status: string }>(request.path, request.init); onRefresh(); } catch { setPullError(true); } finally { setPullSubmitting(false); }
  }
  const bytes = (value?: number) => Number.isFinite(value) ? value! >= 1024 * 1024 * 1024 ? `${(value! / 1024 / 1024 / 1024).toFixed(2)} GiB` : value! >= 1024 * 1024 ? `${(value! / 1024 / 1024).toFixed(1)} MiB` : `${value} B` : 'Unavailable';
  const duration = (value?: number) => !Number.isFinite(value) ? 'Unavailable' : value! >= 86400 ? `${Math.floor(value! / 86400)}d ${Math.floor(value! % 86400 / 3600)}h` : value! >= 3600 ? `${Math.floor(value! / 3600)}h ${Math.floor(value! % 3600 / 60)}m` : `${Math.floor(value! / 60)}m ${value! % 60}s`;
  const active = record.runtime.current_state === 'running' || record.runtime.current_state === 'starting' || record.runtime.current_state === 'stopping';
  const action = (label: string, permission: string, name: ServerAction, icon: React.ReactNode, className?: string) => can(permission) && <button className={className} disabled={serverActionDisabled(name, record.runtime.current_state)} onClick={() => onAction(name)}>{icon}{label}</button>;
  const tabs = [{ id: 'overview', label: 'Overview', icon: LayoutDashboard }, ...(can('Monitoring.View') ? [{ id: 'monitoring', label: 'Monitoring', icon: Gauge }] : []), ...(can('Console.View') ? [{ id: 'console', label: 'Console', icon: SquareTerminal }] : []), ...(can('Files.View') ? [{ id: 'files', label: 'Files', icon: FileCode2 }] : []), ...(can('FTP.View') ? [{ id: 'ftp', label: 'FTP', icon: KeyRound }] : []), ...(can('Ports.View') ? [{ id: 'ports', label: 'Ports', icon: Network }] : []), ...(can('Server.View') ? [{ id: 'configuration', label: 'Configuration', icon: Settings }] : []), ...(hasCapability(globalCapabilities,'Roles.View') ? [{ id: 'access', label: 'Access', icon: ShieldCheck }] : [])] as { id: typeof tab; label: string; icon: typeof LayoutDashboard }[];
  return <section className="panel detail-shell">
    <header className="detail-top"><div className="detail-heading"><button className="quiet icon-button" onClick={onBack} aria-label="Back to servers"><ArrowLeft /></button><span className="detail-icon"><ServerIcon /></span><div className="detail-title"><p className="eyebrow">{record.server.creation_mode} application</p><h1>{record.server.name}</h1><p>{record.server.description || 'Managed GameNode application'}</p></div></div><div className="detail-actions">{action('Start', 'Server.Start', 'start', <Play />)}{action('Stop', 'Server.Stop', 'stop', <CircleStop />, 'quiet')}{action('Restart', 'Server.Restart', 'restart', <RefreshCw />, 'quiet')}</div></header>
    <nav className="detail-tabs" aria-label="Server detail sections">{tabs.map(item => <button key={item.id} className={tab === item.id ? 'active' : ''} onClick={() => setTab(item.id)}><item.icon />{item.label}</button>)}</nav>
    <div className="detail-body">{error && <p className="error notice">{error}</p>}
      {tab === 'overview' && <div className="overview-layout"><div className="overview-main"><section className="subpanel"><SectionHeader title="Runtime overview" description="Lifecycle and process information" /><div className="monitoring"><div><small>Lifecycle state</small><strong><span className={`status ${serverStateTone(record.runtime.current_state)}`}>{runtimeStateLabel(record.runtime.current_state,record.runtime.console_detached)}</span></strong></div><div><small>Health</small><strong><span className={`status ${healthTone(monitoring?.health)}`}>{monitoring ? healthLabel(monitoring.health) : 'Unavailable'}</span></strong></div><div><small>Process ID</small><strong>{record.runtime.pid ?? 'Unavailable'}</strong></div><div><small>Uptime</small><strong>{duration(monitoring?.uptime_seconds)}</strong></div><div><small>Auto-restart</small><strong>{record.server.auto_restart_enabled ? 'Enabled' : 'Disabled'}</strong></div><div><small>Restart status</small><strong>{monitoring?.pending_auto_restart ? 'Pending' : monitoring?.restart_limit_reached ? 'Limit reached' : 'Ready'}</strong></div></div></section><section className="subpanel"><SectionHeader title="Application" description="Configured execution context" /><div className="definition-list"><div className="definition-row"><span>Tenant</span><strong className="tenant-badge"><Building2 />{record.tenant_name || record.server.tenant_id}{onOpenTenant && hasCapability(globalCapabilities, 'Tenants.View') && <button className="quiet field-inline-action" onClick={() => onOpenTenant(record.server.tenant_id)}>View</button>}</strong></div>{isContainer && <div className="definition-row"><span>Runtime</span><strong>Container</strong></div>}{isContainer ? <><div className="definition-row"><span>Working directory</span><code>{record.server.working_directory}</code></div><div className="definition-row"><span>Container command</span><code>{container?.command?.length ? container.command.join(' ') : 'None configured'}</code></div></> : <><div className="definition-row"><span>Working directory</span><code>{record.server.working_directory}</code></div><div className="definition-row"><span>Executable</span><code>{record.server.executable}</code></div><div className="definition-row"><span>Arguments</span><code>{record.server.arguments.length ? record.server.arguments.join(' ') : 'None configured'}</code></div></>}</div></section><RestartSchedulesPanel serverID={record.server.id} token={token} canEdit={can('Server.Edit')} />{isContainer && <section className="subpanel"><SectionHeader title="Container" description="Safe image, resource, and network state" actions={pullActionVisible ? <button disabled={!pullEnabled} onClick={() => void pullImage()}>{pullState === 'pulling' ? 'Pulling image…' : 'Pull Image'}</button> : undefined} />{!container ? <p className="muted">Container details are unavailable.</p> : <><div className="definition-list"><div className="definition-row"><span>Image</span><code>{container.image}</code></div><div className="definition-row"><span>Engine</span><strong><span className={`status ${imageAvailabilityTone(imageAvailability)}`}>{engineAvailabilityLabel(imageAvailability)}</span></strong></div><div className="definition-row"><span>Image availability</span><strong><span className={`status ${imageAvailabilityTone(imageAvailability)}`}>{imageAvailabilityLabel(imageAvailability)}</span></strong></div><div className="definition-row"><span>Pull state</span><strong>{pullStateLabel(pullState) ? <span className={`status ${pullStateTone(pullState)}`}>{pullStateLabel(pullState)}</span> : '—'}</strong></div><div className="definition-row"><span>CPU limit</span><strong>{formatCPULimit(container.cpu_limit_millis)}</strong></div><div className="definition-row"><span>Memory limit</span><strong>{formatMemoryLimit(container.memory_limit_bytes)}</strong></div><div className="definition-row"><span>Network mappings</span><span>{portsLoading ? 'Loading…' : portsError ? 'Unavailable' : containerPorts?.length ? <span className="definition-list">{containerPorts.map((port, index) => <code key={`${port.protocol}-${port.port}-${index}`}>{formatContainerPortMapping(port)}</code>)}</span> : 'No ports configured'}</span></div></div>{imageAvailability === 'missing' && <div className="notice notice--warning"><strong>Image not available locally.</strong><br />Pull the configured image before starting the server.</div>}{imageAvailability === 'engine_unavailable' && <div className="notice notice--warning"><strong>Container engine unavailable.</strong><br />Image availability cannot be checked and Pull Image is unavailable.</div>}{(pullState === 'failed' || pullError) && <div className="notice notice--warning"><strong>Image pull failed.</strong><br />The configured image remains unchanged. Retry when the engine is available.</div>}</>}</section>}{record.runtime.last_error && <div className="notice notice--warning"><strong>Last runtime error</strong><br /><br />{record.runtime.last_error}</div>}</div><aside className="overview-side"><section className="subpanel"><SectionHeader title="Reliability" /><div className="definition-list"><div className="definition-row"><span>Crash count</span><strong>{metric(monitoring?.crash_count)}</strong></div><div className="definition-row"><span>Restart count</span><strong>{metric(monitoring?.restart_count)}</strong></div><div className="definition-row"><span>Restart policy</span><strong>{record.server.auto_restart_enabled ? `${record.server.auto_restart_max_attempts} attempts` : 'Disabled'}</strong></div></div></section>{configuration && <section className="subpanel"><SectionHeader title="Game configuration" description="Managed settings owned by GameNode" /><div className="definition-list"><div className="definition-row"><span>Managed settings</span><strong>{gameConfigSettingCount(configuration)}</strong></div><div className="definition-row"><span>Applies</span><strong>{gameConfigRestartRequired(configuration) ? 'After restart' : 'Immediately'}</strong></div></div><div className="actions"><button className="quiet" onClick={() => setTab('configuration')}><Settings />Open Configuration</button></div></section>}<section className="subpanel danger-zone"><SectionHeader title="Server management" description="Configuration and destructive actions" actions={pullActionVisible ? <button disabled={!pullEnabled} onClick={() => void pullImage()}>{pullState === 'pulling' ? 'Pulling image…' : 'Pull Image'}</button> : undefined} /><div className="actions">{can('Server.Edit') && <button className="quiet" onClick={onEdit}><Pencil />Edit</button>}{can('Server.Update') && <button className="quiet" disabled={active} title={active ? 'Stop the server before updating.' : undefined} onClick={onUpdate}><HardDriveDownload />Update Server</button>}{isAdmin && <button className="quiet" disabled={active} title={active ? 'Stop the server before migrating.' : undefined} onClick={onMigrate}><Building2 />Migrate tenant</button>}{action('Kill process', 'Server.Kill', 'kill', <CircleAlert />, 'danger quiet')}{action('Delete server', 'Server.Delete', 'delete', <CircleAlert />, 'danger quiet')}</div></section></aside></div>}
      {tab === 'monitoring' && can('Monitoring.View') && <section className="monitoring-page"><SectionHeader title="Performance monitoring" description="Bounded in-memory history collected by GameNode" /><div className="monitoring-kpis"><MetricCard label="CPU" value={percent(monitoring?.cpu_percent)} icon={Gauge} tone="info" /><MetricCard label="Memory" value={bytes(monitoring?.memory_bytes)} icon={Activity} /><MetricCard label="Uptime" value={duration(monitoring?.uptime_seconds)} icon={RotateCcw} /><MetricCard label="PID" value={record.runtime.pid ?? 'Unavailable'} icon={ServerIcon} /><MetricCard label="Crashes" value={metric(monitoring?.crash_count)} icon={CircleAlert} tone={monitoring?.crash_count ? 'danger' : 'neutral'} /><MetricCard label="Restarts" value={metric(monitoring?.restart_count)} icon={RefreshCw} /></div><div className="chart-grid"><Sparkline samples={history} field="cpu_percent" label="CPU usage" format={value => `${value.toFixed(1)}%`} /><Sparkline samples={history} field="memory_bytes" label="Memory usage" format={value => bytes(value)} /></div></section>}
      {tab === 'console' && can('Console.View') && <ConsoleTab serverID={record.server.id} serverState={record.runtime.current_state} canSend={can('Console.Send')} />}
      {tab === 'files' && can('Files.View') && <FilesTab serverID={record.server.id} token={token} permissions={record.capabilities} />}
      {tab === 'ftp' && can('FTP.View') && <FTPPanel serverID={record.server.id} token={token} canManage={can('FTP.Manage')} />}
      {tab === 'ports' && can('Ports.View') && <PortsTab serverID={record.server.id} token={token} canManage={can('Ports.Manage')} />}
      {tab === 'configuration' && can('Server.View') && <><GameConfiguration serverID={record.server.id} token={token} canEdit={can('Server.Edit')} canRestart={can('Server.Restart')} onRestart={() => onAction('restart')}/><section className="subpanel config-summary"><SectionHeader title="Runtime configuration" description="Direct-process definition owned by GameNode." actions={can('Server.Edit')?<button onClick={onEdit}><Pencil />Edit runtime</button>:undefined} /><div className="definition-list"><div className="definition-row"><span>Working directory</span><code>{record.server.working_directory}</code></div><div className="definition-row"><span>Executable</span><code>{record.server.executable}</code></div><div className="definition-row"><span>Stop method</span><strong>{record.server.stop_method==='stdin_command'?`Console: ${record.server.stop_command}`:record.server.stop_method==='console_interrupt'?'Windows console interrupt (force-kill fallback)':'Terminate process'}</strong></div><div className="definition-row"><span>Stop timeout</span><strong>{record.server.stop_timeout_seconds} seconds</strong></div><div className="definition-row"><span>Automatic restart</span><strong>{record.server.auto_restart_enabled ? 'Enabled' : 'Disabled'}</strong></div></div></section></>}
      {tab === 'access' && <ServerAccess serverID={record.server.id} token={token} capabilities={globalCapabilities} onOpenRoles={onOpenRoles}/>}
    </div>
  </section>;
}

function Servers({ token, capabilities, isAdmin, selectedServerID, initialForm, onNavigate, onOpenRoles, onOpenTenant }: { token: string; capabilities?: string[]; isAdmin: boolean; selectedServerID?: string; initialForm?: 'create' | 'edit'; onNavigate: (path: string) => void; onOpenRoles?: () => void; onOpenTenant?: (id: string) => void }) {
  const [records, setRecords] = useState<ServerRecord[]>(); const [selected, setSelected] = useState<ServerRecord>(); const [form, setForm] = useState<'create' | 'edit'>(); const [showUpdate, setShowUpdate] = useState(false); const [showMigration, setShowMigration] = useState(false); const [error, setError] = useState('');
  const load = () => api<{ servers: ServerRecord[] }>('/servers').then(result => setRecords(result.servers)).catch(reason => setError(reason.message));
  useEffect(() => { load(); setForm(initialForm); if (selectedServerID) api<ServerRecord>(`/servers/${selectedServerID}`).then(setSelected).catch(reason => setError(reason.message)); else setSelected(undefined); }, [initialForm, selectedServerID]);
  useEffect(() => {
    if (!selected) return;
    let cancelled = false;
    const refresh = () => { void api<ServerRecord>(`/servers/${selected.server.id}`).then(record => { if (!cancelled) setSelected(record); }).catch(reason => { if (!cancelled) setError(reason instanceof Error ? reason.message : 'Server status could not be refreshed'); }); };
    refresh();
    const timer = window.setInterval(refresh, 2000);
    return () => { cancelled = true; window.clearInterval(timer); };
  }, [selected?.server.id]);
  const saved = async (record: ServerRecord) => { const hydrated = await api<ServerRecord>(`/servers/${record.server.id}`); setSelected(hydrated); setForm(undefined); onNavigate(`/server/${record.server.id}`); load(); };
  async function action(name: ServerAction) { if (!selected) return; try { if (name === 'delete') { const active = ['running', 'starting', 'stopping'].includes(selected.runtime.current_state); if (!confirm(`Delete server ${selected.server.name}?${active ? ' Its active process will be force-stopped.' : ''} The working directory and its files will be kept.`)) return; await api<void>(`/servers/${selected.server.id}`, { method: 'DELETE', headers: csrf(token) }); setSelected(undefined); onNavigate('/server'); load(); return; } await saved(await api<ServerRecord>(`/servers/${selected.server.id}/${name}`, { method: 'POST', headers: csrf(token) })); } catch (reason) { setError(reason instanceof Error ? reason.message : 'Request failed'); } }
  if (form) return <ServerForm initial={form === 'edit' ? selected?.server : undefined} token={token} onDone={saved} onCancel={() => { setForm(undefined); onNavigate(selected ? `/server/${selected.server.id}` : '/server'); }} />;
  if (showUpdate && selected) return <ServerUpdateDialog serverID={selected.server.id} serverName={selected.server.name} token={token} onClose={() => setShowUpdate(false)} onCompleted={() => { setShowUpdate(false); void saved(selected); }} />;
  if (showMigration && selected) return <TenantMigrationDialog server={selected} token={token} onCancel={() => setShowMigration(false)} onCompleted={record => { setShowMigration(false); void saved(record); }} />;
  if (selected) return <ServerDetailModern record={selected} token={token} globalCapabilities={capabilities} isAdmin={isAdmin} onBack={() => { setSelected(undefined); onNavigate('/server'); }} onEdit={() => onNavigate(`/server/${selected.server.id}/edit`)} onAction={action} onUpdate={() => setShowUpdate(true)} onRefresh={() => { void api<ServerRecord>(`/servers/${selected.server.id}`).then(setSelected); }} onOpenRoles={onOpenRoles} onOpenTenant={onOpenTenant} onMigrate={() => setShowMigration(true)} error={error} />;
  const canCreate = hasCapability(capabilities, 'Server.Create');
  const globalView = hasCapability(capabilities, 'Server.View');
  return <section><PageHeader eyebrow="Workloads" title="Servers" description="Manage applications running on this GameNode." actions={canCreate ? <button onClick={() => onNavigate('/server/new')}><ServerIcon />Add server</button> : undefined} />{error && <p className="error notice">{error}</p>}<div className="server-list">{!records ? <SkeletonRows count={4} label="Loading servers…" /> : records.length === 0 ? <EmptyState title={globalView || canCreate ? 'No servers yet' : 'No servers available'} description={globalView || canCreate ? 'Add a custom application or adopt an existing installation to manage its lifecycle, files, ports, and monitoring.' : 'No servers have been assigned to your account.'} icon={ServerIcon} action={canCreate ? <button onClick={() => onNavigate('/server/new')}>Add your first server</button> : undefined} /> : records.map(record => <button className="server-card" key={record.server.id} onClick={() => onNavigate(`/server/${record.server.id}`)}><span className="server-card__identity"><strong>{record.server.name}</strong><small>{record.server.description || record.server.working_directory}{record.tenant_name ? ` · ${record.tenant_name}` : ''}</small></span><span className={`status ${serverStateTone(record.runtime.current_state)}`}>{runtimeStateLabel(record.runtime.current_state,record.runtime.console_detached)}</span><span className="server-card__meta"><span>{record.runtime.pid ? `PID ${record.runtime.pid}` : 'No active process'}</span><small>Auto-restart {record.server.auto_restart_enabled ? 'enabled' : 'disabled'}</small></span><ChevronRight className="server-card__arrow" /></button>)}</div></section>;
}

const pageLabels: Record<'dashboard' | 'servers' | 'templates' | 'identity' | 'tenants' | 'nodes' | 'audit' | 'settings' | 'logs', string> = { dashboard: 'Overview', servers: 'Servers', templates: 'Game Library', identity: 'Users & groups', tenants: 'Tenants', nodes: 'Nodes', audit: 'Audit log', settings: 'Settings', logs: 'Application log' };

function DashboardModern({ me, onLogout, preferences, onUpdatePreferences }: { me: Me; onLogout: () => void; preferences: UIPreferences; onUpdatePreferences: (next: Partial<UIPreferences>) => void }) {
  const route = useAppRoute();
  const page = route.page === 'not-found' || route.page === 'status' ? 'dashboard' : route.page;
  const [tenantOpenID, setTenantOpenID] = useState<string>();
  useEffect(() => { applyBranding(me.branding); const update = (event: Event) => applyBranding((event as CustomEvent<Branding>).detail, true); window.addEventListener('gamenode:branding', update); return () => window.removeEventListener('gamenode:branding', update); }, [me.branding]);
  async function logout() { await api('/auth/logout', { method: 'POST', headers: csrf(me.csrf_token) }); onLogout(); }
  const canIdentity = me.user.is_admin || hasCapability(me.capabilities, 'Users.View') || hasCapability(me.capabilities, 'Groups.View') || hasCapability(me.capabilities, 'Roles.View');
  const canAudit = hasCapability(me.capabilities, 'Audit.View'), canSettings = hasCapability(me.capabilities, 'Settings.View'), canReadLog = hasCapability(me.capabilities, 'Log.Read'), canFlushLog = hasCapability(me.capabilities, 'Log.FlushDirectory'), canTemplates = hasCapability(me.capabilities, 'Templates.View') || hasCapability(me.capabilities, 'Templates.Manage'), canTenants = hasCapability(me.capabilities, 'Tenants.View'), canNodes = hasCapability(me.capabilities, 'Node.View');
  const items = [{ id: 'dashboard', label: 'Overview', icon: LayoutDashboard }, { id: 'servers', label: 'Servers', icon: ServerIcon }, ...(canTemplates ? [{ id: 'templates', label: 'Game Library', icon: Package }] : []), ...(canTenants ? [{ id: 'tenants', label: 'Tenants', icon: Building2 }] : []), ...(canNodes ? [{ id: 'nodes', label: 'Nodes', icon: Network }] : []), ...(canIdentity ? [{ id: 'identity', label: 'Users & groups', icon: Users }] : []), ...(canAudit ? [{ id: 'audit', label: 'Audit log', icon: ShieldCheck }] : []), ...((canReadLog || canFlushLog) ? [{ id: 'logs', label: 'Application log', icon: Activity }] : []), ...(canSettings ? [{ id: 'settings', label: 'Settings', icon: Settings }] : [])] as { id: typeof page; label: string; icon: typeof LayoutDashboard }[];
  return <main className="app">
    <aside className="app-sidebar">
      <div className="brand"><span className="brand-mark">GN</span><span className="brand-copy"><strong>GameNode</strong><small>Infrastructure manager</small></span></div>
      <p className="nav-label">Workspace</p>
      <nav aria-label="Primary navigation">{items.map(item => <button key={item.id} className={page === item.id ? 'active' : ''} onClick={() => navigate(item.id === 'servers' ? '/server' : `/${item.id}`)} aria-current={page === item.id ? 'page' : undefined} title={preferences.sidebarCollapsed ? item.label : undefined}><item.icon /><span>{item.label}</span></button>)}</nav>
      <div className="sidebar-footer">
        <div className="user-chip" title={preferences.sidebarCollapsed ? (me.user.display_name || me.user.username) : undefined}><span className="user-avatar">{(me.user.display_name || me.user.username).charAt(0).toUpperCase()}</span><span><strong>{me.user.display_name || me.user.username}</strong><small>{me.user.is_admin ? 'Administrator' : 'Operator'}</small></span></div>
        <button className="quiet" onClick={logout} title={preferences.sidebarCollapsed ? 'Sign out' : undefined}><LogOut /><span>Sign out</span></button>
      </div>
    </aside>
    <div className="content-area">
      <AppTopbar section="Workspace" label={pageLabels[page]} theme={preferences.theme} onThemeChange={theme => onUpdatePreferences({ theme })} collapsed={preferences.sidebarCollapsed} onToggleSidebar={() => onUpdatePreferences({ sidebarCollapsed: !preferences.sidebarCollapsed })} />
      <section className="content">{route.page === 'not-found' ? <EmptyState title="Page not found" description="The requested GameNode page does not exist." icon={CircleAlert} action={<button onClick={() => navigate('/dashboard')}>Go to dashboard</button>} /> : page === 'servers' ? <Servers token={me.csrf_token} capabilities={me.capabilities} isAdmin={me.user.is_admin} selectedServerID={route.page === 'servers' ? route.serverID : undefined} initialForm={route.page === 'servers' ? route.mode === 'new' ? 'create' : route.mode : undefined} onNavigate={navigate} onOpenRoles={() => navigate('/identity/roles')} onOpenTenant={canTenants ? (id) => { setTenantOpenID(id); navigate(`/tenants/${id}`); } : undefined} /> : page === 'templates' && canTemplates ? <TemplatesPage token={me.csrf_token} capabilities={me.capabilities} /> : page === 'tenants' && canTenants ? <TenantsPage token={me.csrf_token} capabilities={me.capabilities} openTenantID={route.page === 'tenants' ? route.tenantID ?? tenantOpenID : tenantOpenID} onOpenServer={(id) => navigate(`/server/${id}`)} /> : page === 'nodes' && canNodes ? <NodesPage token={me.csrf_token} capabilities={me.capabilities} /> : page === 'identity' && canIdentity ? <IdentityAdmin token={me.csrf_token} capabilities={me.capabilities} isAdmin={me.user.is_admin} initialTab={route.page === 'identity' ? route.tab : undefined} /> : page === 'audit' && canAudit ? <AuditLog /> : page === 'logs' && (canReadLog || canFlushLog) ? <ApplicationLogPage token={me.csrf_token} canRead={canReadLog} canFlush={canFlushLog} /> : page === 'settings' && canSettings ? <SettingsPage token={me.csrf_token} canManage={hasCapability(me.capabilities, 'Settings.Manage')} canReadLog={canReadLog} canFlushLog={canFlushLog} preferences={preferences} onUpdatePreferences={onUpdatePreferences} /> : <DashboardOverview canCreate={hasCapability(me.capabilities, 'Server.Create')} canAudit={canAudit} canNodes={canNodes} onAudit={() => navigate('/audit')} onServers={() => navigate('/server')} onNodes={() => navigate('/nodes')} />}</section>
    </div>
  </main>;
}

function App() {
  const { preferences, update: updatePreferences } = useUIPreferences();
  const route = useAppRoute();
  const [mode, setMode] = useState<'loading' | 'storage' | 'setup' | 'login' | 'dashboard'>('loading'); const [me, setMe] = useState<Me>(); const [storage, setStorage] = useState<SetupStorage>(); const [setupPolicy, setSetupPolicy] = useState<PasswordPolicy>({ password_minimum_length: 8, password_maximum_length: 256 });
  useEffect(() => { Promise.all([api<SetupStatus>('/setup/status'), api<Me>('/auth/me').catch(() => undefined)]).then(([setup, current]) => { setSetupPolicy(setup.password_policy); applyBranding(setup.branding ?? defaultBranding); if (current) { setMe(current); applyBranding(current.branding); setMode('dashboard'); } else { setStorage(setup.storage); setMode(setup.setup_required && setup.storage ? 'storage' : setup.setup_required ? 'setup' : 'login'); } }); }, []);
  // Purely decorative, fixed-position wallpaper layer: mounted for every
  // screen (including setup/login) so a chosen wallpaper is visible
  // everywhere, but it never affects layout, focus order, or hit-testing.
  const wallpaper = <><div className="wallpaper-layer" aria-hidden="true" /><div className="wallpaper-scrim" aria-hidden="true" /></>;
  if (mode === 'loading') return <>{wallpaper}<main className="auth"><LoadingState label="Starting GameNode…" /></main></>;
  if (mode === 'storage' && storage) return <>{wallpaper}<SetupStorageForm storage={storage} onContinue={() => setMode('setup')} /></>;
  const credentials = <Credentials setup={mode === 'setup'} passwordPolicy={setupPolicy} onComplete={current => { setMe(current); setMode('dashboard'); }} />;
  if (route.page === 'status' && mode !== 'setup') return <StatusPage key={me ? 'authenticated' : 'anonymous'} slug={route.slug} login={credentials} />;
  return <>{wallpaper}{mode === 'dashboard' && me ? <DashboardModern me={me} onLogout={() => { setMe(undefined); setMode('login'); }} preferences={preferences} onUpdatePreferences={updatePreferences} /> : credentials}</>;
}

createRoot(document.getElementById('root')!).render(<App />);
